package webui

const pageHTML = `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Hostpack</title>
  <link rel="stylesheet" href="/assets/app.css">
</head>
<body>
  <main>
    <header>
      <div><p class="eyebrow">HOSTPACK CONTROL ROOM</p><h1>Minecraft fleet status</h1></div>
      <div id="connection" class="connection">Connecting…</div>
    </header>
    <section class="hero panel">
      <div><p class="label">Lifecycle</p><div class="phase"><span id="phase-dot"></span><strong id="phase">—</strong></div></div>
      <div><p class="label">Active pack</p><strong id="active">None</strong><small id="hostname">—</small></div>
      <div><p class="label">Backup</p><strong id="generation">Generation 0</strong><small id="backup">Current</small></div>
      <div><p class="label">Updated</p><strong id="updated">—</strong><small id="clock">—</small></div>
    </section>
    <section><div class="section-title"><h2>Configured packs</h2><span id="pack-count"></span></div><div id="packs" class="pack-grid"></div></section>
    <section class="logs-section">
      <div class="section-title"><h2>Recent logs</h2><div class="log-tools"><input id="filter" aria-label="Filter logs" placeholder="Filter logs"><label><input id="follow" type="checkbox" checked> Follow</label></div></div>
      <pre id="logs" class="logs panel" tabindex="0">Waiting for logs…</pre>
    </section>
  </main>
  <script src="/assets/app.js"></script>
</body>
</html>`

const appCSS = `:root{color-scheme:dark;--bg:#08110e;--panel:#101d18;--line:#263a31;--text:#f1f7f3;--muted:#8da59a;--green:#61e89a;--amber:#ffc45c;--red:#ff7676}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% 0,#183127 0,transparent 36rem),var(--bg);color:var(--text);font:15px/1.5 ui-sans-serif,system-ui,-apple-system,sans-serif}main{width:min(1180px,calc(100% - 32px));margin:0 auto;padding:42px 0 64px}header,.section-title,.log-tools{display:flex;align-items:center;justify-content:space-between;gap:18px}h1{font-size:clamp(28px,5vw,50px);line-height:1.05;letter-spacing:-.04em;margin:4px 0 0}h2{font-size:18px;margin:0}.eyebrow,.label{color:var(--muted);font-size:11px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;margin:0}.connection{border:1px solid var(--line);border-radius:999px;padding:8px 13px;color:var(--muted)}.connection.online{color:var(--green);border-color:#2f6546}.panel{background:linear-gradient(145deg,rgba(21,39,32,.96),rgba(12,24,19,.96));border:1px solid var(--line);box-shadow:0 20px 60px rgba(0,0,0,.22);border-radius:18px}.hero{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;margin:34px 0 42px;overflow:hidden}.hero>div{padding:23px;min-width:0;background:rgba(255,255,255,.012)}.hero strong{display:block;font-size:20px;margin-top:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.hero small{display:block;color:var(--muted);margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.phase{display:flex;align-items:center;gap:10px}.phase span{width:10px;height:10px;border-radius:50%;background:var(--muted);box-shadow:0 0 16px currentColor}.phase.ready span,.phase.idle span{background:var(--green)}.phase.failed span{background:var(--red)}.phase.loading span,.phase.recovering span,.phase.resizing span,.phase.saving span,.phase.draining span{background:var(--amber)}.pack-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px;margin:15px 0 42px}.pack{padding:19px;border:1px solid var(--line);border-radius:14px;background:rgba(15,29,23,.72)}.pack.active{border-color:#438a60;box-shadow:inset 0 0 0 1px #438a60}.pack h3{margin:0 0 4px;font-size:16px}.pack .host{color:var(--green);font:12px ui-monospace,SFMono-Regular,monospace;overflow-wrap:anywhere}.metrics{display:flex;gap:8px;flex-wrap:wrap;margin-top:15px}.metric{background:#0a1511;border:1px solid var(--line);border-radius:8px;padding:5px 8px;color:var(--muted);font-size:12px}.section-title{margin-bottom:14px}.section-title>span{color:var(--muted)}input[type=text],input:not([type]){background:#0a1511;border:1px solid var(--line);border-radius:9px;color:var(--text);padding:8px 10px;width:min(240px,42vw)}label{color:var(--muted);font-size:13px;white-space:nowrap}.logs{height:430px;overflow:auto;padding:18px;margin:0;color:#bad0c4;font:12px/1.65 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere}.error{color:var(--red)}@media(max-width:760px){main{padding-top:24px}header{align-items:flex-start}.hero{grid-template-columns:1fr 1fr}.log-tools{align-items:flex-end;flex-direction:column}.logs{height:360px}}@media(max-width:480px){.hero{grid-template-columns:1fr}.connection{font-size:12px}}`

const appJS = `const $=id=>document.getElementById(id);let allLogs=[];function escText(value){return value==null?'—':String(value)}function renderStatus(data){const s=data.state||{};const phase=s.phase||'IDLE';$('phase').textContent=phase;$('phase').parentElement.className='phase '+phase.toLowerCase();$('active').textContent=s.activeId||'None';$('hostname').textContent=s.activeId?s.activeId+'.'+data.domain:'No pack selected';$('generation').textContent='Generation '+(s.generation||0);$('backup').textContent=s.backupPending?'Backup pending':(s.lastError||'Current');$('backup').className=s.backupPending||s.lastError?'error':'';$('updated').textContent=s.updatedAt?new Date(s.updatedAt).toLocaleTimeString():'—';$('clock').textContent='Server '+new Date(data.now).toLocaleString();$('pack-count').textContent=data.packs.length+' packs';$('packs').replaceChildren(...data.packs.map(p=>{const card=document.createElement('article');card.className='pack'+(p.id===s.activeId?' active':'');const title=document.createElement('h3');title.textContent=p.displayName;const host=document.createElement('div');host.className='host';host.textContent=p.id+'.'+data.domain;const metrics=document.createElement('div');metrics.className='metrics';[p.provider,'Java '+p.java,(p.heapMb/1024).toFixed(1)+' GB heap',(p.machineMemoryMb/1024).toFixed(1)+' GB VM',p.machineCpus+' vCPU'].forEach(v=>{const e=document.createElement('span');e.className='metric';e.textContent=v;metrics.append(e)});card.append(title,host,metrics);return card}))}function formatLog(line){try{const e=JSON.parse(line);const time=e.time?new Date(e.time).toLocaleTimeString():'';const level=e.level||'';const msg=e.msg||'';delete e.time;delete e.level;delete e.msg;const details=Object.keys(e).length?' '+JSON.stringify(e):'';return [time,level,msg].filter(Boolean).join(' ') + details}catch{return line}}function renderLogs(){const query=$('filter').value.toLowerCase();const lines=allLogs.map(formatLog).filter(line=>line.toLowerCase().includes(query));const box=$('logs');box.textContent=lines.join('\n')||'No matching logs.';if($('follow').checked)box.scrollTop=box.scrollHeight}async function refresh(){try{const [status,logs]=await Promise.all([fetch('/api/status'),fetch('/api/logs?limit=300')]);if(!status.ok||!logs.ok)throw new Error('request failed');renderStatus(await status.json());allLogs=(await logs.json()).logs||[];renderLogs();$('connection').textContent='Live';$('connection').className='connection online'}catch(error){$('connection').textContent='Reconnecting…';$('connection').className='connection'}}$('filter').addEventListener('input',renderLogs);refresh();setInterval(refresh,3000);`
